INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7492830, 1193150, 103142, '<td valign="top">This was beautifully done. Great catch!</td>', 'This was beautifully done. Great catch!', '2017-01-18 05:25:21.000000', NULL, 0),
(7492835, 1192891, 98565, '<td valign="top">Dear Fina<br/> <br/>So sorry that your lovely firework display didn''t score better.<br/>The Challenge was about a resolution - something you want to achieve or change in the New Year: that is missing in your picture and maybe the reason why voters didn''t rate it higher. This picture would have done better in the "Holiday Cheer" challenge I think.<br/>Can you handle postprocessing? To darken the sky might have helped too. If you want me to help you just contact me, ok?<br/>Don''t be sad, just go for the next time<br/></td>', 'Dear Fina So sorry that your lovely firework display didn''t score better.The Challenge was about a resolution - something you want to achieve or change in the New Year: that is missing in your picture and maybe the reason why voters didn''t rate it higher. This picture would have done better in the "Holiday Cheer" challenge I think.Can you handle postprocessing? To darken the sky might have helped too. If you want me to help you just contact me, ok?Don''t be sad, just go for the next time', '2017-01-18 06:33:11.000000', NULL, 0),
(7492840, 1192818, 83548, '<td valign="top">I thought this was the best photo in the challenge.  Great capture.</td>', 'I thought this was the best photo in the challenge.  Great capture.', '2017-01-18 07:06:26.000000', NULL, 0),
(7492843, 1193125, 59029, '<td valign="top">One of my 7s and pick for the blue, well done Alessandro!</td>', 'One of my 7s and pick for the blue, well done Alessandro!', '2017-01-18 07:44:37.000000', NULL, 0),
(7492844, 1192891, 1031, '<td valign="top">I finished one whole place ahead of you -- I don''t think the voters were impressed by burning things this time.<br/> <br/>I also agree this might have done better if color-shifted to resemble a "normal" fireworks shot with a night sky.<br/> <br/>In the meantime, keep shooting and experimenting, and don''t worry too much about the scores here -- if <u>you</u> are happy with it then it is a "good" photo.</td>', 'I finished one whole place ahead of you -- I don''t think the voters were impressed by burning things this time. I also agree this might have done better if color-shifted to resemble a "normal" fireworks shot with a night sky. In the meantime, keep shooting and experimenting, and don''t worry too much about the scores here -- if you are happy with it then it is a "good" photo.', '2017-01-18 07:48:37.000000', NULL, 0),
(7492850, 1192891, 100831, '<td valign="top">I love the delicacy of this! Can you post your exif?</td>', 'I love the delicacy of this! Can you post your exif?', '2017-01-18 08:45:37.000000', NULL, 0),
(7492866, 1192891, 63218, '<td valign="top">Love what you do. Do what you love. Take lots of pictures. Participate in every challenge by thoughtfully voting and commenting. The worst place to finish is in the middle of the pack--this photo came in last, which means people had a reaction to it that they didn''t like. So, if you can change the reaction to ''like'' it will score higher. As you discover what you like, and shoot it, your pictures will become uniquely yours.  People will respond to that. This is of course only one opinion.</td>', 'Love what you do. Do what you love. Take lots of pictures. Participate in every challenge by thoughtfully voting and commenting. The worst place to finish is in the middle of the pack--this photo came in last, which means people had a reaction to it that they didn''t like. So, if you can change the reaction to ''like'' it will score higher. As you discover what you like, and shoot it, your pictures will become uniquely yours.  People will respond to that. This is of course only one opinion.', '2017-01-18 10:08:43.000000', NULL, 0),
(7492888, 1193319, 50695, '<td valign="top">stunning. you really got color to work for you.</td>', 'stunning. you really got color to work for you.', '2017-01-18 11:24:34.000000', NULL, 0),
